import { test, expect } from '@playwright/test';

test.describe('User Login with Valid Credentials', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in with valid credentials and navigate to dashboard', async ({ page }) => {
    // Setup: intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Intercept the dashboard API call
    await page.route('**/api/dashboard', (route) => {
      route.continue();
    });

    // Verify login form is visible
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Fill in valid credentials
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('validPassword123');

    // Click login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify login success message appears
    const successMessage = page.getByText(/logged in successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify dashboard route is active
    const dashboardRoute = page.route('**/api/dashboard');
    await expect(dashboardRoute).toHaveBeenFired();

    // Verify dashboard is visible
    const dashboardNav = page.getByRole('navigation', { name: /dashboard/i });
    await expect(dashboardNav).toBeVisible();

    // Verify dashboard content is loaded
    const dashboardContent = page.getByText(/dashboard content/i);
    await expect(dashboardContent).toBeVisible();

    // Verify user is logged in
    const userProfile = page.getByText(/user@example.com/i);
    await expect(userProfile).toBeVisible();
  });

  test('should display error message when login fails with invalid credentials', async ({ page }) => {
    // Setup: intercept the login API call with invalid credentials
    await page.route('**/api/auth/login', (route) => {
      route.abort('failed');
    });

    // Verify login form is visible
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Fill in invalid credentials
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('invalidEmail');

    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('wrongPassword');

    // Click login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Verify login form is still visible
    await expect(loginForm).toBeVisible();

    // Verify dashboard route is not active
    const dashboardRoute = page.route('**/api/dashboard');
    await expect(dashboardRoute).not.toHaveBeenFired();

    // Verify login button is still clickable
    await expect(loginButton).toBeEnabled();
  });
});
